[SRSReportParameterAttribute(classstr(METPOContinuingPermissionNoticeContract))]
class METPOContinuingPermissionNoticeDP extends SrsReportDataProviderPreProcessTempDB
{
    RecordInsertList insertList;
    METPOContinuingPermissionNoticeHeaderTmp header;
    METPOContinuingPermissionNoticeLineTmp line;
    PurchTable purchTable;

}

Method.Source:
/// <summary>
/// Process report
/// </summary>
public void processReport()
{
    METPOContinuingPermissionNoticeContract contract = this.parmDataContract() as METPOContinuingPermissionNoticeContract;

    PurchId purchId = contract.parmPurchId();
    purchTable = PurchTable::find(purchId);

    PurchLine purchLineNegative;

    select firstonly RecId from purchLineNegative
        where purchLineNegative.PurchId == purchTable.PurchId
        && purchLineNegative.PurchQty < 0;

    METPurchTable metPurchTable = METPurchTable::find(purchTable.PurchId);

    if (purchTable.RecId && metPurchTable.UnderBond && purchLineNegative.RecId && metPurchTable.VendorReturn)
    {
        this.insertHeaderData();
    }
}

/// <summary>
/// Inserts the report header data.
/// </summary>
public void insertHeaderData()
{
    METVendTable vendTable = METVendTable::find(purchTable.OrderAccount);

    METCPNumber cpNumber = purchTable.metPurchTable().ContinuingPermissionNoticeNumber;

    if (!cpNumber)
    {
        NumberSequenceReference numberSequenceReference;

        numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METCPNumber));

        if (numberSequenceReference.RecId)
        {
            cpNumber = NumberSeq::newGetNum(numberSequenceReference).num();
        }
    }

    header.ContinuingPermissionNoticeNumber = cpNumber;

    CompanyInfo companyInfo = CompanyInfo::find();
    InventSite site;

    select firstonly METBondNumber from site
        where site.SiteId == purchTable.InventSiteId;

    InventLocation inventLocation;

    select firstonly METWHSubEntity, Name, RecId from inventLocation
        where inventLocation.InventLocationId == purchTable.InventLocationId;

    header.CompanyLogo = this.getCompanyLogo(companyInfo.METLegalEntityType, inventLocation.METWHSubEntity);
    LogisticsEntityPostalAddressView postalAddressView = this.getWareHousePrimaryAddress(inventLocation.RecId);

    header.SendingBranchAddress = postalAddressView.Address;
    header.SendingBranchName = inventLocation.Name;
    header.ReceivingBranchAddress = VendTable::find(purchTable.OrderAccount).postalAddress().Address;
    header.ReceivingBranchName = VendTable::find(purchTable.OrderAccount).name();
    header.NoticeDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone()));
    header.NoticeTimeString = int2Str(DateTimeUtil::time(DateTimeUtil::utcNow()));
    header.CompanyName = companyInfo.Name;

    List metBondList = strSplit(site.METBondNumber, ' ');
    Container metBondCon = list2con(metBondList);

    header.SenderBranchExciseNumber = conpeek(metBondCon, 1);
    header.SenderBranchBondNumber = conpeek(metBondCon, 2);
    header.ReceivingBranchExciseNumber = vendTable.ExciseNumber;
    header.ReceivingBranchBondNumber = vendTable.BondNumber;
    header.ReturnPurchaseOrder = purchTable.PurchId;
    header.insert();

    METPurchTable metPurchTable;

    select firstonly metPurchTable
        where metPurchTable.PurchId == purchTable.PurchId;

    if (metPurchTable.RecId)
    {
        ttsbegin;
        // Update existing record
        metPurchTable.selectForUpdate(true);
        metPurchTable.ContinuingPermissionNoticeNumber = header.ContinuingPermissionNoticeNumber;
        metPurchTable.update();
        ttscommit;
    }
    else
    {
        // Insert new record
        metPurchTable.PurchId = purchTable.PurchId;
        metPurchTable.ContinuingPermissionNoticeNumber = header.ContinuingPermissionNoticeNumber;
        metPurchTable.insert();
    }

    this.insertLineData();
}

/// <summary>
///  Inserts the report line data.
/// </summary>
public void insertLineData()
{
    const str defaultUOM = 'EA';
    PurchLine purchLine;
    InventTable inventTable;
    InventDim inventDim;
    METInventTable metInventTable;

    METExciseRegisterEntry exciseRegister;
    METExciseInformationTable metExciseInformationTable;
    METTariffItemCodeBase tariffCodeBase;
    insertList = new RecordInsertList(tableNum(METPOContinuingPermissionNoticeLineTmp), false, false, false, false, false, line);

    while select purchLine
        where purchLine.PurchId == purchTable.PurchId
    join inventTable
        where purchLine.ItemId == inventTable.ItemId
    outer join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
    outer join TariffItem from tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
    outer join RecId from inventDim
        where inventDim.inventDimId == purchLine.InventDimId
    outer join forupdate metExciseInformationTable
        where metExciseInformationTable.InventTransType == InventTransType::Purch  &&
        metExciseInformationTable.ReferenceNumber == purchLine.PurchId &&
        metExciseInformationTable.ItemId == purchLine.ItemId &&
        metExciseInformationTable.SiteId == inventDim.InventSiteId &&
        metExciseInformationTable.Lodgement == ''
    {
        METLodgement lodgement;

        if (metExciseInformationTable.RecId)
        {
            lodgement = this.getMetLodgement(metExciseInformationTable);

            if (lodgement)
            {
                List lodgementList = strSplit(lodgement, ';');
                ListEnumerator enum = lodgementList.getEnumerator();

                while (enum.moveNext())
                {
                    line.BondMark = any2Str(enum.current());

                    this.prepareRecordListTmp(purchLine, inventTable, metInventTable, tariffCodeBase, lodgement);
                }
            }
            else
            {
                this.prepareRecordListTmp(purchLine, inventTable, metInventTable, tariffCodeBase, lodgement);
            }
        }
        else
        {
            this.prepareRecordListTmp(purchLine, inventTable, metInventTable, tariffCodeBase, lodgement);
        }
    }

    insertList.insertDatabase();
}

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METPOContinuingPermissionNoticeHeaderTmp</returns>
[SRSReportDataSetAttribute(tableStr(METPOContinuingPermissionNoticeHeaderTmp))]
public METPOContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;

    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METPOContinuingPermissionNoticeLineTmp</returns>
[SRSReportDataSetAttribute(tableStr(METPOContinuingPermissionNoticeLineTmp))]
public METPOContinuingPermissionNoticeLineTmp dsLines()
{
    select line;

    return line;
}

/// <summary>
/// Get METcash logo based on entity
/// </summary>
/// <param name = "_legalEntityType">LegalEntityType</param>
/// <param name = "_subEntityWareHouse">SubEntity warehouse</param>
/// <returns>Image</returns>
public container getCompanyLogo(METLegalEntityType _legalEntityType, InventLocationId _subEntityWareHouse)
{
    container image;

    switch (_legalEntityType)
    {
        case METLegalEntityType::Food:
            image = SysDocuBrandImages::getImage(_subEntityWareHouse);
            break;

        case METLegalEntityType::Liquor:
            image = SysDocuBrandImages::getImage(METConstants::LiquorLogo);
            break;

        default:
            break;

    }
    return image;
}

/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

private void prepareRecordListTmp(PurchLine _purchLine, InventTable _inventTable, METInventTable _metInventTable, METTariffItemCodeBase _tariffCodeBase, METLodgement _lodgement)
{
    const str defaultUOM = 'EA';

    METExciseRegisterEntry exciseRegister;
    METPurchLine metPurchLine;

    if (_lodgement)
    {
        // Find the matching purch line
        select firstonly metPurchLine
            where metPurchLine.PurchLine == _purchLine.RecId;

        if (metPurchLine.RecId)
        {
            ttsbegin;
            // Update existing record
            metPurchLine.selectForUpdate(true);
            metPurchLine.Lodgement = _lodgement;
            metPurchLine.update();
            ttscommit;
        }
        else
        {
            // Insert new record
            metPurchLine.PurchLine = _purchLine.RecId;
            metPurchLine.Lodgement = _lodgement;
            metPurchLine.insert();
        }
    }

    select TIUV, DutyRateReceived from exciseRegister
            where exciseRegister.OrderNumber == purchTable.PurchId
            && exciseRegister.ItemId == _purchLine.ItemId;

    METPurchaseWMSFactor purchaseWMSFactor = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(_purchLine.PurchUnit).RecId, UnitOfMeasure::findBySymbol(defaultUOM).RecId, EcoResProduct::findByProductNumber(_purchLine.ItemId).RecId).Factor;
    line.BottlesSupplied = abs(purchaseWMSFactor * _purchLine.PurchQty);
    line.ItemId = _purchLine.ItemId;
    line.ItemDescription = _inventTable.productName(SystemParameters::getSystemLanguageId());
    line.BottleSize = _metInventTable.BottleSize;
    line.PackQty = _metInventTable.ItemPack;
    line.Strength = _metInventTable.AlcoholContent;
    line.PurchUoM = _purchLine.PurchUnit;
    line.Quantity = _purchLine.PurchQty;
    line.LitresOfAlcoholCalculated = abs(_metInventTable.BottleSize * line.BottlesSupplied * _metInventTable.AlcoholContent);
    line.ValueTIU = exciseRegister.TIUV;
    line.TariffItem = _tariffCodeBase.TariffItem;
    line.CountryOfOrigin = _metInventTable.CountryCode;
    line.StatCode = _metInventTable.statcode();
    line.ValueDuty = exciseRegister.DutyRateReceived;
    line.InvoiceAccount = purchTable.InvoiceAccount;
    line.PurchId = purchTable.PurchId;
    insertList.add(line);
}

/// <summary>
/// Gets the lodgement details for the updated excise information table.
/// </summary>
/// <param name = "_metExciseInformationTable">_metExciseInformationTable buffer</param>
/// <returns>Returns the concatenated lodgement details.</returns>
private METLodgement getMetLodgement(METExciseInformationTable _metExciseInformationTable)
{
    METExciseInformationTable       metExciseInformationTablePO;
    METAvailableQty                 purchAvailableQty;
    METAvailableQty                 purchAvailableQtyOrig;
    METLodgement                    metLodgement;

    try
    {
        ttsbegin;

        container                       lodgementQtyCon;

        select forupdate metExciseInformationTablePO
        order by CreatedDateTime
            where metExciseInformationTablePO.InventTransType == InventTransType::Purch &&
                metExciseInformationTablePO.ItemId == _metExciseInformationTable.ItemId &&
                metExciseInformationTablePO.SiteId == _metExciseInformationTable.SiteId &&
                metExciseInformationTablePO.LodgementClosed == NoYes::No;

        if (metExciseInformationTablePO.RecId != 0)
        {
            purchAvailableQty  =  metExciseInformationTablePO.AvailableQty -  abs(_metExciseInformationTable.InventoryQty);
            metLodgement = metExciseInformationTablePO.Lodgement;

            if (purchAvailableQty > 0)
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(_metExciseInformationTable.InventoryQty)];

                metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                metExciseInformationTablePO.update();

                _metExciseInformationTable.Lodgement = metExciseInformationTablePO.Lodgement;
                _metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                _metExciseInformationTable.update();
            }
            else
            {
                lodgementQtyCon += [metExciseInformationTablePO.Lodgement, abs(metExciseInformationTablePO.AvailableQty)];

                metExciseInformationTablePO.AvailableQty = 0;
                metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                metExciseInformationTablePO.update();

                do
                {
                    next metExciseInformationTablePO;

                    if (metExciseInformationTablePO.RecId == 0)
                    {
                        Error(strFmt("@MET:LodgementValidation", _metExciseInformationTable.ItemId, _metExciseInformationTable.SiteId));
                        break;
                    }
                    purchAvailableQtyOrig = abs(purchAvailableQty);
                    purchAvailableQty  =  metExciseInformationTablePO.AvailableQty - abs(purchAvailableQty);

                    metLodgement = metLodgement + ','+  metExciseInformationTablePO.Lodgement;

                    if (purchAvailableQty > 0)
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, purchAvailableQtyOrig];

                        metExciseInformationTablePO.AvailableQty = purchAvailableQty;
                        metExciseInformationTablePO.update();

                        break;
                    }
                    else
                    {
                        lodgementQtyCon += [metExciseInformationTablePO.Lodgement, metExciseInformationTablePO.AvailableQty];

                        metExciseInformationTablePO.AvailableQty = 0;
                        metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
                        metExciseInformationTablePO.update();
                    }
                }
                while (purchAvailableQty < 0);

                _metExciseInformationTable.Lodgement = metLodgement;
                _metExciseInformationTable.LodgementAndQtyCon = lodgementQtyCon;
                _metExciseInformationTable.update();
            }

            info(strFmt("@MET:LodgmentUpdate", _metExciseInformationTable.ItemId, _metExciseInformationTable.SiteId));
        }
        else
        {
            Error(strFmt("@MET:LodgementValidation", _metExciseInformationTable.ItemId, _metExciseInformationTable.SiteId));
        }
        ttscommit;
    }
    catch
    {
        exceptionTextFallThrough();
    }

    return metLodgement;
}
